          <textarea ref={composer} aria-label="Повідомлення навчальному помічнику" value={prompt} maxLength={2400} disabled={!enabled || loading} rows={2} onKeyDown={keyDown} onChange={event => setPrompt(event.target.value)} placeholder={format?.placeholder || (thread.length ? 'Запитай далі…' : 'Напиши запитання…')} />
