      {bundle.plan.length > 0 && <details className="mta-inline-artifact" open={bundle.mode === 'plan'}><summary><Clock3 size={16} /><span>План підготовки</span><small>{bundle.plan.length} {bundle.plan.length===1?'крок':bundle.plan.length<5?'кроки':'кроків'}</small></summary><MaxTutorPlanActivity run={run} enabled={enabled} saveState={saveState} onProgress={onProgress} activeStepId={planStepId} selectionRevision={planSelectionRevision}/></details>}
